"""For every run whose uncapped LS path is not 'delete extras only to S0' (or S0 not in start): replay start mode + uncapped LS and log each step.
Output F_pathinspect.md (observations)."""
import csv, math, sys
import numpy as np
import f_common as fc, bvs_core as bc
import f1_run, f2_run, f1x_run

ROWS = {}
for m in (f1_run, f2_run, f1x_run): ROWS.update(m.ROWS)
out = ["# Path inspection (runs with non-deletion moves, truth removal, S0 not in start, or final != S0)", "",
       "Generated by f_path_inspect.py (replays start mode and uncapped LS0 with bvs_core). `gain` = F(new) - F(old) in nats; T = centre before the move; |T\S0| = number of nulls in T; "
       "for a truth removal also F(T - j) - F(T) and the nulls of T within the same group-of-5 (S5) / index distance <= 2 (AR1) of j.", ""]
for f in ('F1_raw.csv', 'F2_raw.csv', 'F1X_raw.csv'):
    for r in csv.DictReader(open(f)):
        if r['path_final_S0'] == 'True' and r['path_all_del_extras'] == 'True' and r['S0_in_start'] == 'True':
            continue
        row = ROWS[r['id']]; s = int(r['seed'])
        X, _ = fc.build_X(row); n, p = X.shape
        y, eps = fc.make_y(row, X, s); K = min(p, n // 2)
        prob = bc.Problem(X, y, K); S0 = tuple(sorted(row['S0'])); S0set = set(S0)
        info = bc.start_mode(prob, bc.partition(X)); St = tuple(sorted(info.mode))
        res = bc.local_search(prob, St, 10 ** 4)
        out.append(f"## {r['id']} seed {s}: start {St} (S0={S0}); S0 in start {r['S0_in_start']}; uncapped final {res['final']} certified {res['certified']}; Z-less F(S0)-F(final) = {prob.F(S0)-prob.F(res['final']):.3f}")
        for a, b in zip(res['path'][:-1], res['path'][1:]):
            sa, sb = set(a), set(b)
            if len(sb) < len(sa): mv = f"del {sorted(sa - sb)}"
            elif len(sb) > len(sa): mv = f"add {sorted(sb - sa)}"
            else: mv = f"swap {sorted(sa - sb)} -> {sorted(sb - sa)}"
            line = f"* T has {len(a)} elements ({len(sa - S0set)} nulls); {mv}; gain {prob.F(b)-prob.F(a):.3f}"
            rem = sa - sb
            if len(sb) <= len(sa) and rem & S0set:
                j = next(iter(rem & S0set))
                near = [e for e in sa - S0set if (e // 5 == j // 5 if row['kind'] == 's5' else abs(e - j) <= 2)]
                line += f"; TRUTH {j} removed, F(T-j)-F(T) = {prob.F(tuple(sorted(sa - {j})))-prob.F(a):+.3f}; nulls near j in T: {sorted(near)}"
            out.append(line)
        out.append("")
open('F_pathinspect.md', 'w', encoding='utf-8').write("\n".join(out) + "\n")
